
import { isWeex } from 'universal-env';
import  StringFormat , {StringData, Description, Variable, FormatOptions}from "./string-format";
import { error } from './util';

interface Instances {
  [name: string]: any; // eslint-disable-line
}

interface InitOptions {
  [name: string]: any; // eslint-disable-line
}

declare const global: {[key: string]: any}; // eslint-disable-line
declare const window: {[key: string]: any}; // eslint-disable-line

const NAMESPACE = '__GLOBAL_STRING_FORMAT__';

// for weex
const INSTANCES_CACHE: Instances = {};

// for SSR, this should be one-time context
let DISPOSABLES__CACHE: Instances;

function getInstances(context?: Instances): Instances{
  if (context) {
    DISPOSABLES__CACHE = context;
    return context;
  }
  if (DISPOSABLES__CACHE) {
    return DISPOSABLES__CACHE;
  }
  if (isWeex) { // in weex use instances
    return INSTANCES_CACHE;
  }
  const g = typeof global !== 'undefined' ? global : window;
  if (!g[NAMESPACE]) {
    g[NAMESPACE] = {};
  }
  return g[NAMESPACE];
}

export function init(locale: string, strings: StringData, options: InitOptions = {}): StringFormat  {
  const {name='default', context} = options;
  const instances = getInstances(context);
  const stringFormat = new StringFormat(locale, strings);
  instances[name] = stringFormat;
  return stringFormat;
}

export function format(des: Description, variable: Variable,  options: FormatOptions = {} ): string {
  const {name = 'default'} = options;
  const instances = getInstances();
  const instance = instances[name];
  if(!instance){
    error(`
    Not found instance named ${name},
    make sure to call formatString.format() after formatString.init()
    `);
    return des.defaultMessage || des.id || '';
    
  }
  const string = instance.format(des, variable, options);
  return string;
}

export default {
  init,
  format,
  StringFormat
};
export const sdkVersion = "1.0.8";